}
``

After:
```js
function resolveTrackerType(config, options) {
 if (options && options.trackerOverride) { return options.trackerOverride; }
 var trackerType = null;
 try { trackerType = java.lang.System.getenv('DEFAULT_TRACKER'); } catch (e) {}
